tool_args.command:
ARTIFACTS="/home/ubuntu/.agent-ml-research-be-idea-gen-0519-4/projects/policy_ambiguity_safety/artifacts"
DEST="/tmp/anon_repo_push/artifacts"

# Check what we're missing by comparing top-level items
echo "=== Items in artifacts NOT copied ==="
for item in "$ARTIFACTS"/*; do
    name=$(basename "$item")
    case "$name" in
        .venv|__pycache__|=1.11.0|=1.24.0|=1.50.0|=2.0.0) echo "EXCLUDED (junk): $name" ;;
        _last_visual_review.json|_paper_figure.lock|_paper_figure_result.json) echo "EXCLUDED (internal): $name" ;;
        dream_reports) echo "EXCLUDED (internal): $name" ;;
        review_issues.yaml|review_reports|review_round_*) echo "EXCLUDED (review): $name" ;;
        _project) 
            if [ ! -d "$DEST/_project" ]; then echo "MISSING: $name"; else echo "INCLUDED: $name"; fi ;;
        citation_verification.json|citation_verification_urgent.json) echo "EXCLUDED (internal): $name" ;;
        emnlp_arr_checklist_draft.md) echo "EXCLUDED (internal): $name" ;;
        api_fallback_comparison.md) echo "EXCLUDED (internal): $name" ;;
        r14_rho_computation.md) echo "EXCLUDED (internal): $name" ;;
        auth_scope_audit) echo "EXCLUDED (internal audit): $name" ;;
        plan_011|plan_014) echo "CHECK: $name" ;;
        temp_pilot) echo "CHECK: $name" ;;
        tool_response_supplement_log.json) echo "CHECK: $name" ;;
        README.md) echo "WILL REPLACE: $name" ;;
        *)
            if [ -d "$item" ]; then
                [ -d "$DEST/$name" ] && echo "INCLUDED dir: $name" || echo "MISSING dir: $name"
            else
                [ -f "$DEST/$name" ] && echo "INCLUDED file: $name" || echo "MISSING file: $name"
            fi
            ;;
    esac
done
